CREATE TABLE public.profiles(id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '' CHECK(length(display_name)<=100)); GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role; ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY; CREATE POLICY own_profiles ON public.profiles FOR ALL TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid()); CREATE FUNCTION public.create_myworld_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,left(coalesce(NEW.raw_user_meta_data->>'display_name',''),100)); RETURN NEW; END; $$; CREATE TRIGGER myworld_profile_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_myworld_profile(); INSERT INTO public.profiles(id) SELECT id FROM auth.users ON CONFLICT DO NOTHING;
CREATE TYPE public.app_role AS ENUM('admin','user'); CREATE TABLE public.user_roles(user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE,role public.app_role,PRIMARY KEY(user_id,role)); GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role; ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY; CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid()); CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$; REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated;
CREATE TABLE public.event_records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),submitter_id uuid NOT NULL,event jsonb NOT NULL,status text NOT NULL DEFAULT 'pending_review' CHECK(status IN('pending_review','published','changes_requested','rejected','archived')),review_reason text NOT NULL DEFAULT '',duplicate_matches jsonb NOT NULL DEFAULT '[]',reviewer_id uuid,reviewed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.event_records TO anon,authenticated; GRANT ALL ON public.event_records TO service_role; ALTER TABLE public.event_records ENABLE ROW LEVEL SECURITY; CREATE POLICY published_events ON public.event_records FOR SELECT TO anon,authenticated USING(status='published'); CREATE POLICY own_events ON public.event_records FOR SELECT TO authenticated USING(submitter_id=auth.uid()); CREATE POLICY admin_events ON public.event_records FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.event_contacts(event_id uuid PRIMARY KEY REFERENCES public.event_records(id) ON DELETE CASCADE,contact_email text NOT NULL CHECK(length(contact_email)<=255)); GRANT SELECT ON public.event_contacts TO authenticated; GRANT ALL ON public.event_contacts TO service_role; ALTER TABLE public.event_contacts ENABLE ROW LEVEL SECURITY; CREATE POLICY private_contacts ON public.event_contacts FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.event_records e WHERE e.id=event_id AND(e.submitter_id=auth.uid() OR public.has_role(auth.uid(),'admin'))));
CREATE TABLE public.event_review_history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid REFERENCES public.event_records(id),reviewer_id uuid NOT NULL,action text NOT NULL,reason text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.event_review_history TO authenticated; GRANT ALL ON public.event_review_history TO service_role; ALTER TABLE public.event_review_history ENABLE ROW LEVEL SECURITY; CREATE POLICY admin_history ON public.event_review_history FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.published_event_urls(url text PRIMARY KEY,event_id uuid REFERENCES public.event_records(id)); GRANT ALL ON public.published_event_urls TO service_role; ALTER TABLE public.published_event_urls ENABLE ROW LEVEL SECURITY;